@tool
def gitea_user_post_users_by_username_tokens(username, body: dict | None = None, confirmed: bool = False) -> dict:
    """Create an access token

    Service: gitea  |  POST /users/{username}/tokens
    Write op — first call returns requires_approval; re-call with confirmed=True after user confirms."""
    return _call(
        "gitea",
        "POST",
        f"/users/{username}/tokens",
        body=body,
        confirmed=confirmed,
    )


@tool
def gitea_user_delete_users_by_username_tokens_by_token(username, token, confirmed: bool = False) -> dict:
    """delete an access token

    Service: gitea  |  DELETE /users/{username}/tokens/{token}
    Write op — first call returns requires_approval; re-call with confirmed=True after user confirms."""
    return _call(
        "gitea",
        "DELETE",
        f"/users/{username}/tokens/{token}",
        confirmed=confirmed,
    )

